return $input.all().map(item => {
  const text = item.json?.text
    || item.json?.response?.text
    || item.json?.output
    || item.json?.response?.generations?.[0]?.[0]?.text
    || item.json?.generations?.[0]?.[0]?.text;

  if (!text) {
    return {
      json: {
        status: "failed",
        reason: "No text found",
        rawKeys: Object.keys(item.json),
        raw: JSON.stringify(item.json).slice(0, 500)
      }
    };
  }

  const cleaned = text
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  try {
    const parsed = JSON.parse(cleaned);
    return { json: { ...parsed, status: "success" } };
  } catch (e) {
    return {
      json: {
        connection_request: "",
        "1st_followup": "",
        "2nd_followup": "",
        status: "failed",
        reason: "JSON parse error: " + e.message,
        raw: cleaned
      }
    };
  }
});

